// ─── PARTICLE CANVAS ──────────────────────────────────────────
function ParticleField() {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: -9999, y: -9999 });
  const animRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let W = window.innerWidth,
      H = window.innerHeight;
    canvas.width = W;
    canvas.height = H;

    const NUM = Math.min(120, Math.floor((W * H) / 12000));
    const particles = Array.from({ length: NUM }, () => ({
      x: Math.random() * W,
      y: Math.random() * H,
      vx: (Math.random() - 0.5) * 0.3,
      vy: (Math.random() - 0.5) * 0.3,
      r: Math.random() * 1.5 + 0.3,
      alpha: Math.random() * 0.6 + 0.1,
      color:
        Math.random() > 0.7
          ? [52, 211, 153]
          : Math.random() > 0.5
            ? [99, 102, 241]
            : [148, 163, 184],
    }));

    const onResize = () => {
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W;
      canvas.height = H;
    };
    const onMouse = (e) => {
      mouseRef.current = { x: e.clientX, y: e.clientY };
    };
    window.addEventListener("resize", onResize);
    window.addEventListener("mousemove", onMouse);

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      const mx = mouseRef.current.x,
        my = mouseRef.current.y;

      particles.forEach((p) => {
        // Mouse repulsion
        const dx = p.x - mx,
          dy = p.y - my;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 120) {
          const force = (120 - dist) / 120;
          p.vx += (dx / dist) * force * 0.08;
          p.vy += (dy / dist) * force * 0.08;
        }
        // Damping
        p.vx *= 0.97;
        p.vy *= 0.97;
        p.x += p.vx;
        p.y += p.vy;
        if (p.x < 0) p.x = W;
        if (p.x > W) p.x = 0;
        if (p.y < 0) p.y = H;
        if (p.y > H) p.y = 0;

        // Draw dot
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${p.color[0]},${p.color[1]},${p.color[2]},${p.alpha})`;
        ctx.fill();
      });

      // Draw connections
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const a = particles[i],
            b = particles[j];
          const dx = a.x - b.x,
            dy = a.y - b.y;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d < 100) {
            ctx.beginPath();
            ctx.moveTo(a.x, a.y);
            ctx.lineTo(b.x, b.y);
            ctx.strokeStyle = `rgba(52,211,153,${0.08 * (1 - d / 100)})`;
            ctx.lineWidth = 0.5;
            ctx.stroke();
          }
        }
      }
      animRef.current = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(animRef.current);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("mousemove", onMouse);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: "fixed",
        inset: 0,
        pointerEvents: "none",
        zIndex: 0,
        opacity: 0.7,
      }}
    />
  );
}

// ─── CINEMATIC HEADLINE ───────────────────────────────────────
function CinematicHeadline({ delay = 0 }) {
  const [visibleWords, setVisibleWords] = useState(0);
  useEffect(() => {
    const t = setTimeout(() => {
      const interval = setInterval(() => {
        setVisibleWords((n) => {
          if (n >= HEADLINE_WORDS.length) {
            clearInterval(interval);
            return n;
          }
          return n + 1;
        });
      }, 90);
      return () => clearInterval(interval);
    }, delay);
    return () => clearTimeout(t);
  }, [delay]);

  return (
    <h1
      style={{
        fontSize: "clamp(38px,4.5vw,64px)",
        fontWeight: 900,
        lineHeight: 1.06,
        letterSpacing: "-0.04em",
        margin: "0 0 22px",
        color: "#f1f5f9",
      }}
    >
      {HEADLINE_WORDS.map((word, i) => {
        const isAccent = i >= 5; // "one habit at a time" gets the gradient
        return (
          <span
            key={i}
            style={{
              display: "inline-block",
              marginRight: "0.28em",
              opacity: i < visibleWords ? 1 : 0,
              transform: i < visibleWords ? "none" : "translateY(18px)",
              transition:
                "opacity 0.4s ease, transform 0.4s cubic-bezier(0.16,1,0.3,1)",
              ...(isAccent
                ? {
                    background:
                      "linear-gradient(135deg, #34d399 0%, #06b6d4 50%, #818cf8 100%)",
                    WebkitBackgroundClip: "text",
                    WebkitTextFillColor: "transparent",
                    backgroundClip: "text",
                  }
                : { color: "#f1f5f9" }),
            }}
          >
            {word}
          </span>
        );
      })}
    </h1>
  );
}

