function PrimaryBtn({
  onClick,
  loading,
  loadingText,
  children,
  type = "submit",
}) {
  const [hov, setHov] = useState(false);
  return (
    <button
      type={type}
      onClick={onClick}
      disabled={loading}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      style={{
        width: "100%",
        padding: "15px",
        borderRadius: "14px",
        fontSize: "15px",
        fontWeight: 900,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: "8px",
        border: "none",
        cursor: loading ? "wait" : "pointer",
        background: loading
          ? "rgba(52,211,153,0.5)"
          : "linear-gradient(135deg, #34d399 0%, #10b981 60%, #059669 100%)",
        color: "#032212",
        boxShadow:
          hov && !loading
            ? "0 0 40px rgba(52,211,153,0.55), 0 8px 25px rgba(52,211,153,0.3), inset 0 1px 0 rgba(255,255,255,0.3)"
            : "0 0 20px rgba(52,211,153,0.25), 0 4px 12px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.2)",
        transform: hov && !loading ? "translateY(-2px) scale(1.01)" : "none",
        transition: "all 0.2s cubic-bezier(0.16,1,0.3,1)",
        letterSpacing: "-0.01em",
      }}
    >
      {loading ? (
        <>
          <Spinner />
          {loadingText}
        </>
      ) : (
        children
      )}
    </button>
  );
}

